      "title": "Effects of Interest Rate and Exchange Rate Changes",
      "source_segment_ids": ["FCT_0004","CON_0044","CON_0045","CON_0046","CON_0047","CON_0025","CON_0026"],
      "mode": "visual_only",
      "remaining_text": "",
      "visuals": [
        {
          "type": "table",
          "needs_review": false,
          "missing_information": null,
          "evidence": [
            {
              "note_id": "FCT_0004",
              "exact_quote": "Rising US interest rates led to an appreciation of the dollar."
            },
            {
              "note_id": "CON_0044",
              "exact_quote": "When the domestic interest rate is increased relative to the rest of the world, the exchange rate must appreciate."
            },
            {
              "note_id": "CON_0045",
              "exact_quote": "An expansionary domestic monetary policy leads to a contraction in output and an appreciation of the currency."
            },
            {
              "note_id": "CON_0046",
              "exact_quote": "If the domestic interest rate changes while the rest of the world does not, the differential must be compensated."
            },
            {
              "note_id": "CON_0047",
              "exact_quote": "Compensation for a higher interest rate differential comes through an expected capital loss on the currency."
            },
            {
              "note_id": "CON_0025",
              "exact_quote": "The price of foreign currency in terms of domestic currency; it moves up (appreciates) when the domestic interest rate rises relative to the foreign interest rate."
            },
            {
              "note_id": "CON_0026",
              "exact_quote": "The return on a bond or loan; when the domestic interest rate is higher than the foreign rate, the domestic currency tends to appreciate."
            }
          ],
          "payload": {
            "type": "table",
            "title": "Interest Rate Changes and Their Exchange‑Rate/Output Effects",
            "headers": ["Condition", "Result"],
            "rows": [
              ["Rising US interest rates", "appreciation of the dollar"],
              ["Domestic interest rate ↑ vs rest of world", "exchange rate must appreciate"],
              ["Expansionary domestic monetary policy", "contraction in output and currency appreciation"],
              ["Domestic interest rate changes alone", "differential must be compensated"],
              ["Higher interest rate differential", "expected capital loss on the currency"],
              ["Domestic interest rate ↑ relative to foreign", "foreign currency price moves up (appreciates)"],
              ["Domestic interest rate > foreign rate", "domestic currency tends to appreciate"]
            ]
          }
        }
      ]
    }
  ]
}
